mapper.select:
select e.user_id as userId, u.username, u.birthday, u.address, u.email, u.description, u.province, u.city, u.country, u.origin, u.inservice, e.`name`, e.gender, e.mobile_phone as mobiePhone, e.telephone, e.identity, e.work_status as workStatus, e.work_type as workType, e.contract_signing_date as contractSigningDate, e.entry_date as entryDate, e.graduated_school as graduatedSchool, e.education, e.discount, e.leave_time as leaveTime, e.title, e.post_level as postLevel, e.emergency_contact as emergencyContact, e.emergency_contact_phone as emergencyContactPhone, e.photo, e.diploma_photo as diplmaPhone, e.crt_id as crtId, upst.company_id as orgId, upst.department_id as orgDeptId, upst.post_id as postId from sys_employee e LEFT JOIN sys_user u on u.id = e.user_id left join sys_user_post upst on upst.user_id = e.user_id
and e.`name` LIKE CONCAT(CONCAT('%',#{form.name}),'%')
and upst.post_id = #{form.postId}
and e.work_status = #{form.workStatus}
